scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script 탭에서 scwin.inputCalendar2_onviewchange 부분을 확인한다.
    //1. In the Script tab, check scwin.inputCalendar2_onviewchange.
    //1. Review comments
    //Test step 2. scwin.inputCalendar2_onyearselect 부분을 확인한다.
    //2. Check the scwin.inputCalendar2_onyearselect part.
    //2. Confirm comments
    //Test step 3. scwin.inputCalendar2_onmonthselect 부분을 확인한다.
    //3. Check scwin.inputCalendar2_onmonthselect.
    //3. Confirm comments
    //Test step4. 브라우저에서 달력아이콘을 클릭해서 년도를 변경한다. (예 : 2017년 -> 2019년)
    //4. Click the calendar icon in your browser to change the year. (E.g. 2017 -> 2019)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_year_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_year_itemTable_41').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_img').click()");
    //Verify 4. 'info.oldValue===2017 info.newValue===2019' 팝업이 생성된다.
    //4. 'info.oldValue === 2017 info.newValue === 2019' Pop-up is generated.
    WebSquare.wUnit.addCommand("assert", "window.log", "true");
    // WebSquare.wUnit.addCommand("pause", "1000");
    //Test 5. 이번에는 월을 변경한다. (예 : 02월 -> 07월)
    //5. Change the month this time. (Example: February -> July)
//    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_img').click()");
//    WebSquare.wUnit.addCommand("pause", "500");
//    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_month_button').click()");
//    WebSquare.wUnit.addCommand("pause", "500");
//    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_month_itemTable_4').click()");
//    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 'info.oldValue===2 info.newValue===5' 팝업이 생성된다.
    //5. 'info.oldValue === 2 info.newValue === 5' Popup is created.
//    WebSquare.wUnit.addCommand("assert", "window.log1", "true");
//    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
